415→// ── UI state ──────────────────────────────────────────────────────────────
416→
417→/**
418→ * Lifecycle states of the Claude agent process:
419→ * - `idle`      — no process running, ready to spawn
420→ * - `spawning`  — process launched, waiting for CLI to connect via WS
421→ * - `connected` — CLI connected and `system/init` received
422→ * - `thinking`  — waiting for assistant response
423→ * - `done`      — `result` message received, process finished
424→ * - `error`     — process crashed or unexpected failure
425→ */
426→export type AgentStatus = "idle" | "spawning" | "connected" | "thinking" | "done" | "disconnected" | "error";
427→
428→export type ChatMessageRole = "user" | "assistant" | "system";
429→
430→/**
431→ * A single entry in the chat message list. System messages include
432→ * session init info and result summaries. Messages with a `controlRequest`
433→ * are rendered as tool-approval cards instead of plain bubbles.
434→ */
435→/** A single option in an AskUserQuestion question. */
436→export interface UserQuestionOption {
437→  label: string;
438→  description?: string;
439→}
440→
441→/** A single question from AskUserQuestion. */
442→export interface UserQuestion {
443→  question: string;
444→  header?: string;
445→  options: UserQuestionOption[];
446→  multiSelect: boolean;
447→}
448→
449→/** Info about a single tool_use block in an assistant message. */
450→export interface ToolCallInfo {
451→  name: string;
452→  toolUseId?: string;
453→  /** Truncated one-line preview of the tool result, if available. */
454→  resultPreview?: string;
455→  /** Raw tool input data, preserved for file-modifying tools (Edit, Write, MultiEdit). */
456→  input?: Record<string, unknown>;
457→}
458→
459→export interface ChatMessage {
460→  id: string;
461→  role: ChatMessageRole;
462→  content: string;
463→  timestamp: number;
464→  /** Present when this message represents a tool approval request. */
465→  controlRequest?: {
466→    id: string;
467→    tool_name: string;
468→    input: Record<string, unknown>;
469→    /** Tool description from the protocol, if available. */
470→    description?: string;
471→    /** Set to true after the user allows or denies. */
472→    resolved?: boolean;
473→    /** Whether the user allowed (true) or denied (false). */
474→    allowed?: boolean;
475→  };
476→  /** Present when this message is an AskUserQuestion control request. */
477→  userQuestion?: {
478→    requestId: string;
479→    questions: UserQuestion[];
480→    resolved?: boolean;
481→  };
482→  /** Tool calls found in this assistant message. */
483→  toolCalls?: ToolCallInfo[];
484→  /** True when this message has only tool_use/tool_result blocks and no text. */
485→  isToolOnly?: boolean;
486→}
