329→
330→/** Server sends the full list of agents after every state change. */
331→export interface ServerAgentList {
332→  type: "agent_list";
333→  agents: AgentInfo[];
334→}
335→
336→/** Server confirms a new agent was spawned and assigns its ID. */
337→export interface ServerSpawned {
338→  type: "spawned";
339→  agentId: string;
340→}
341→
342→/** Server sends full message history for an agent (in response to `request_history`). */
343→export interface ServerMessageHistory {
344→  type: "message_history";
345→  agentId: string;
346→  messages: ServerMessage[];
347→}
348→
349→/** CLI WebSocket disconnected (process may have crashed or exited). */
350→export interface ServerCliDisconnected {
351→  type: "cli_disconnected";
352→  agentId: string;
353→}
354→
355→/** CLI WebSocket reconnected (e.g. after relaunch with --resume). */
356→export interface ServerCliConnected {
357→  type: "cli_connected";
358→  agentId: string;
359→}
360→
361→/** Server confirms message history was cleared for an agent. */
362→export interface ServerHistoryCleared {
363→  type: "history_cleared";
364→  agentId: string;
365→}
366→
367→/** Server sends the full workspace list to the browser. */
368→export interface ServerWorkspaceList {
369→  type: "workspace_list";
370→  workspaces: Workspace[];
371→}
372→
373→/** Server responds with a directory listing for the folder browser. */
374→export interface ServerDirectoryListing {
375→  type: "directory_listing";
376→  path: string;
377→  entries: DirectoryEntry[];
378→}
379→
380→/** Server sends the full task list to the browser. */
381→export interface ServerTaskList {
382→  type: "task_list";
383→  tasks: Task[];
384→}
385→
386→/** Server confirms a task was updated. */
387→export interface ServerTaskUpdated {
388→  type: "task_updated";
389→  task: Task;
390→}
391→
392→/** Server confirms a task was deleted. */
393→export interface ServerTaskDeleted {
394→  type: "task_deleted";
395→  taskId: string;
396→}
397→
398→/** Union of all messages the WS server can send to the browser. */
399→export type ServerMessage =
400→  | ServerRelay
401→  | ServerStatus
402→  | ServerError
403→  | ServerAgentList
404→  | ServerSpawned
405→  | ServerMessageHistory
406→  | ServerCliDisconnected
407→  | ServerCliConnected
408→  | ServerHistoryCleared
409→  | ServerWorkspaceList
410→  | ServerDirectoryListing
411→  | ServerTaskList
412→  | ServerTaskUpdated
413→  | ServerTaskDeleted;
