488→// ── Task system ──────────────────────────────────────────────────────────
489→
490→// ── Notifications ──────────────────────────────────────────────────────────
491→
492→export type NotificationType = "done" | "error" | "control_request" | "question";
493→
494→export interface NotificationItem {
495→  id: string;
