504→// ── Tasks ──────────────────────────────────────────────────────────────────
505→
506→export type TaskStatus = "icebox" | "todo" | "in-progress" | "done";
507→export type TaskPriority = "low" | "medium" | "high" | "urgent";
508→
509→/** A user-created task, optionally linked to a Claude agent. */
