400→/** A single item in the context menu. */
401→function ContextMenuItem({
402→  label,
403→  onClick,
404→  destructive,
405→}: {
406→  label: string;
407→  onClick: () => void;
408→  destructive?: boolean;
409→}) {
410→  return (
411→    <button
412→      onClick={onClick}
413→      className={cn(
414→        "flex w-full px-3 py-1.5 text-xs transition-colors",
415→        destructive
416→          ? "text-red-500 hover:bg-red-500/10"
417→          : "hover:bg-accent"
418→      )}
419→    >
420→      {label}
421→    </button>
422→  );
