459→/** Inline input for renaming an agent. */
460→function RenameInput({
461→  initialValue,
462→  onConfirm,
463→  onCancel,
464→}: {
465→  initialValue: string;
466→  onConfirm: (value: string) => void;
467→  onCancel: () => void;
468→}) {
469→  const [value, setValue] = useState(initialValue);
470→  const inputRef = useRef<HTMLInputElement>(null);
471→
472→  useEffect(() => {
473→    inputRef.current?.focus();
474→    inputRef.current?.select();
475→  }, []);
476→
477→  function handleKeyDown(e: React.KeyboardEvent) {
478→    e.stopPropagation();
479→    if (e.key === "Enter") {
480→      const trimmed = value.trim();
481→      if (trimmed) onConfirm(trimmed);
482→      else onCancel();
483→    } else if (e.key === "Escape") {
484→      onCancel();
485→    }
486→  }
487→
488→  return (
489→    <input
490→      ref={inputRef}
491→      type="text"
492→      value={value}
493→      onChange={(e) => setValue(e.target.value)}
494→      onKeyDown={handleKeyDown}
495→      onBlur={() => {
496→        const trimmed = value.trim();
497→        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
498→        else onCancel();
499→      }}
500→      onClick={(e) => e.stopPropagation()}
501→      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
502→    />
503→  );
504→}
