293→                variant="ghost"
294→                size="icon-xs"
295→                onClick={() => setInboxOpen((v) => !v)}
296→                title="Notifications"
297→                className={cn((inboxOpen || unreadCount > 0) && "text-primary")}
298→              >
299→                <Bell className="size-3.5" />
300→                {unreadCount > 0 && (
301→                  <span className="absolute -top-0.5 -right-0.5 flex size-3.5 items-center justify-center rounded-full bg-red-500 text-[8px] font-bold text-white">
302→                    {unreadCount > 9 ? "9+" : unreadCount}
303→                  </span>
304→                )}
305→              </Button>
306→              {inboxOpen && notifications && onSelectNotification && onDismissNotification && onClearNotifications && onToggleNotifications && (
307→                <NotificationInbox
308→                  notifications={notifications}
309→                  enabled={!!notificationsEnabled}
310→                  onToggleEnabled={onToggleNotifications}
311→                  onSelect={(agentId, notifId) => {
312→                    onSelectNotification(agentId, notifId);
313→                    setInboxOpen(false);
314→                  }}
315→                  onDismiss={onDismissNotification}
316→                  onClear={onClearNotifications}
317→                  onClose={() => setInboxOpen(false)}
318→                />
319→              )}
320→            </div>
321→          )}
322→          {onOpenSfxSettings && (
323→            <Button
324→              variant="ghost"
325→              size="icon-xs"
326→              onClick={onOpenSfxSettings}
327→              title="Sound settings"
328→            >
329→              <Volume2 className="size-3.5" />
330→            </Button>
331→          )}
332→        </div>
333→      </div>
334→    </div>
335→  );
336→}
