"use client";

/**
 * Top bar showing the WS connection state (green/red dot), the current
 * agent lifecycle status, active model name, and a model selector dropdown.
 */

import { useEffect, useRef, useState } from "react";
import { Bell, BellOff, ChevronDown, GitCompareArrows, ListTodo, Menu, Volume2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Tip } from "@/components/ui/tip";
import { NotificationInbox } from "./notification-inbox";
import { cn } from "@/lib/utils";
import type { AgentStatus, NotificationItem } from "@/lib/types";

/** Human-readable labels for each agent status. */
const STATUS_LABELS: Record<AgentStatus, string> = {
  idle: "idle",
  spawning: "spawning...",
  connected: "connected",
  thinking: "thinking...",
  done: "done",
  disconnected: "disconnected",
  error: "error",
};

/** Curated list of common models for the dropdown. */
const MODEL_PRESETS = [
  { value: "", label: "Default (CLI)", description: "Use CLI default model" },
  { value: "claude-sonnet-4-20250514", label: "Sonnet 4", description: "Claude Sonnet 4" },
  { value: "claude-opus-4-20250514", label: "Opus 4", description: "Claude Opus 4" },
  { value: "qwen3-coder", label: "Qwen3 Coder", description: "Ollama — Qwen3 Coder" },
  { value: "devstral", label: "Devstral", description: "Ollama — Devstral" },
];

export function StatusBar({
  connected,
  status,
  agentLabel,
  activeModel,
  selectedModel,
  onModelChange,
  showRaw,
  onToggleRaw,
  showTasks,
  onToggleTasks,
  showDiffs,
  onToggleDiffs,
  onToggleSidebar,
  onOpenSfxSettings,
  notificationsEnabled,
  onToggleNotifications,
  notifications,
  onSelectNotification,
  onDismissNotification,
  onClearNotifications,
  onTestNotification,
}: {
  connected: boolean;
  status: AgentStatus;
  agentLabel?: string | null;
  activeModel?: string | null;
  selectedModel?: string;
  onModelChange?: (model: string) => void;
  showRaw?: boolean;
  onToggleRaw?: () => void;
  showTasks?: boolean;
  onToggleTasks?: () => void;
  showDiffs?: boolean;
  onToggleDiffs?: () => void;
  onToggleSidebar?: () => void;
  onOpenSfxSettings?: () => void;
  notificationsEnabled?: boolean;
  onToggleNotifications?: () => void;
  notifications?: NotificationItem[];
  onSelectNotification?: (agentId: string, notificationId: string) => void;
  onDismissNotification?: (id: string) => void;
  onClearNotifications?: () => void;
  onTestNotification?: () => void;
}) {
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [customInput, setCustomInput] = useState("");
  const [showCustom, setShowCustom] = useState(false);
  const [inboxOpen, setInboxOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const customInputRef = useRef<HTMLInputElement>(null);

  const unreadCount = notifications?.filter((n) => !n.read).length ?? 0;

  // Close dropdown on click-outside or Escape
  useEffect(() => {
    if (!dropdownOpen) return;
    function handleClick(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setDropdownOpen(false);
        setShowCustom(false);
      }
    }
    function handleKey(e: KeyboardEvent) {
      if (e.key === "Escape") {
        setDropdownOpen(false);
        setShowCustom(false);
      }
    }
    document.addEventListener("mousedown", handleClick);
    document.addEventListener("keydown", handleKey);
    return () => {
      document.removeEventListener("mousedown", handleClick);
      document.removeEventListener("keydown", handleKey);
    };
  }, [dropdownOpen]);

  // Focus custom input when it appears
  useEffect(() => {
    if (showCustom) customInputRef.current?.focus();
  }, [showCustom]);

  /** Shorten a model name for display (e.g. "claude-sonnet-4-20250514" → "sonnet-4"). */
  function shortModel(model: string): string {
    // Match known preset labels
    const preset = MODEL_PRESETS.find((p) => p.value === model);
    if (preset && preset.value) return preset.label;
    // Strip "claude-" prefix and date suffix for Claude models
    const m = model.replace(/^claude-/, "").replace(/-\d{8}$/, "");
    return m || model;
  }

  const displayModel = activeModel ?? (selectedModel || null);
  const isActive = status === "connected" || status === "thinking";

  return (
    <div className="flex items-center justify-between border-b px-2 py-2 text-xs md:px-4">
      {/* Left side */}
      <div className="flex items-center gap-2">
        {onToggleSidebar && (
          <button
            onClick={onToggleSidebar}
            className="rounded p-1 transition-colors hover:bg-muted/50 md:hidden"
            aria-label="Toggle sidebar"
          >
            <Menu className="size-4" />
          </button>
        )}
        <span className="text-muted-foreground font-semibold hidden md:inline">thos dashboard</span>
        <span className="text-muted-foreground font-semibold md:hidden">thos</span>
        {agentLabel && (
          <>
            <span className="text-muted-foreground/50">/</span>
            <Tip text={agentLabel}><span className="truncate max-w-[150px] md:max-w-[250px] font-medium text-foreground/80">{agentLabel}</span></Tip>
          </>
        )}
      </div>

      {/* Right side */}
      <div className="flex items-center gap-1.5 md:gap-3">
        <span className="flex items-center gap-1.5">
          <span
            className={`inline-block size-2 rounded-full ${
              connected ? "bg-green-500" : "bg-red-500"
            }`}
          />
          <span className="hidden md:inline">
            {connected ? "ws connected" : "ws disconnected"}
          </span>
        </span>
        <span className="text-muted-foreground hidden md:inline">|</span>
        <span className="hidden md:inline">agent: {STATUS_LABELS[status]}</span>
        <span className="text-[10px] md:hidden">{STATUS_LABELS[status]}</span>

        {/* Model display + selector */}
        {onModelChange && (
          <>
            <span className="text-muted-foreground hidden md:inline">|</span>
            <div className="relative" ref={dropdownRef}>
              <button
                onClick={() => setDropdownOpen((v) => !v)}
                className={cn(
                  "flex items-center gap-1 rounded px-1.5 py-0.5 font-mono transition-colors",
                  "hover:bg-muted/80 text-muted-foreground",
                  dropdownOpen && "bg-muted"
                )}
                title={displayModel ? `Model: ${displayModel}` : "Select model for next spawn"}
              >
                <span className="max-w-[120px] truncate text-[10px] md:text-xs md:max-w-[180px]">
                  {displayModel ? shortModel(displayModel) : "model"}
                </span>
                <ChevronDown className="size-3 shrink-0" />
              </button>

              {dropdownOpen && (
                <div className="absolute right-0 top-full z-50 mt-1 min-w-[220px] rounded-md border bg-popover p-1 shadow-md">
                  {isActive && activeModel && (
                    <div className="px-2 py-1.5 text-[10px] text-muted-foreground border-b mb-1">
                      Active: <span className="font-mono">{activeModel}</span>
                    </div>
                  )}
                  <div className="px-2 py-1 text-[10px] text-muted-foreground uppercase tracking-wider">
                    Next spawn
                  </div>
                  {MODEL_PRESETS.map((preset) => (
                    <button
                      key={preset.value}
                      onClick={() => {
                        onModelChange(preset.value);
                        setDropdownOpen(false);
                        setShowCustom(false);
                      }}
                      className={cn(
                        "flex w-full flex-col rounded px-2 py-1.5 text-left transition-colors hover:bg-accent",
                        selectedModel === preset.value && "bg-accent"
                      )}
                    >
                      <span className="text-xs font-medium">{preset.label}</span>
                      <span className="text-[10px] text-muted-foreground">{preset.description}</span>
                    </button>
                  ))}
                  <div className="my-1 border-t" />
                  {showCustom ? (
                    <form
                      onSubmit={(e) => {
                        e.preventDefault();
                        const val = customInput.trim();
                        if (val) {
                          onModelChange(val);
                          setCustomInput("");
                          setShowCustom(false);
                          setDropdownOpen(false);
                        }
                      }}
                      className="px-2 py-1"
                    >
                      <input
                        ref={customInputRef}
                        type="text"
                        value={customInput}
                        onChange={(e) => setCustomInput(e.target.value)}
                        placeholder="e.g. llama3.3:70b"
                        className="w-full rounded border bg-background px-2 py-1 text-xs outline-none focus:ring-1 focus:ring-ring"
                      />
                    </form>
                  ) : (
                    <button
                      onClick={() => setShowCustom(true)}
                      className="flex w-full rounded px-2 py-1.5 text-left text-xs text-muted-foreground transition-colors hover:bg-accent"
                    >
                      Custom model...
                    </button>
                  )}
                </div>
              )}
            </div>
          </>
        )}

        <span className="text-muted-foreground hidden md:inline">|</span>
        <div className="flex items-center gap-1.5">
          {onToggleRaw && (
            <button
              onClick={onToggleRaw}
              className={cn(
                "rounded px-2 py-0.5 text-[10px] font-mono transition-colors",
                showRaw
                  ? "bg-foreground text-background"
                  : "bg-muted text-muted-foreground hover:bg-muted/80"
              )}
            >
              {showRaw ? "RAW" : "raw"}
            </button>
          )}
          {onToggleDiffs && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onToggleDiffs}
              title="Toggle diffs"
              className={cn(showDiffs && "text-primary")}
            >
              <GitCompareArrows className="size-3.5" />
            </Button>
          )}
          {onToggleTasks && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onToggleTasks}
              title="Toggle tasks"
              className={cn(showTasks && "text-primary")}
            >
              <ListTodo className="size-3.5" />
            </Button>
          )}
          {onToggleNotifications && (
            <div className="relative">
              <Button
                variant="ghost"
                size="icon-xs"
                onClick={() => setInboxOpen((v) => !v)}
                title="Notifications"
                className={cn((inboxOpen || unreadCount > 0) && "text-primary")}
              >
                <Bell className="size-3.5" />
                {unreadCount > 0 && (
                  <span className="absolute -top-0.5 -right-0.5 flex size-3.5 items-center justify-center rounded-full bg-red-500 text-[8px] font-bold text-white">
                    {unreadCount > 9 ? "9+" : unreadCount}
                  </span>
                )}
              </Button>
              {inboxOpen && notifications && onSelectNotification && onDismissNotification && onClearNotifications && onToggleNotifications && (
                <NotificationInbox
                  notifications={notifications}
                  enabled={!!notificationsEnabled}
                  onToggleEnabled={onToggleNotifications}
                  onSelect={(agentId, notifId) => {
                    onSelectNotification(agentId, notifId);
                    setInboxOpen(false);
                  }}
                  onDismiss={onDismissNotification}
                  onClear={onClearNotifications}
                  onClose={() => setInboxOpen(false)}
                  onTestPush={onTestNotification}
                />
              )}
            </div>
          )}
          {onOpenSfxSettings && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={onOpenSfxSettings}
              title="Sound settings"
            >
              <Volume2 className="size-3.5" />
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

content.content:
  1→"use client";
  2→
  3→/**
  4→ * Sidebar listing all agents with status dots, truncated labels,
  5→ * tmux session names, and a "+" button to spawn a new agent.
  6→ *
  7→ * Split into two sections:
  8→ * - **Active**: agents with status `spawning`, `connected`, or `thinking`.
  9→ * - **Archived**: agents with status `done`, `disconnected`, or `error` (read-only).
 10→ *
 11→ * Right-click (or kebab icon) context menu supports: Rename, Kill, Clear History, Delete.
 12→ * Rename swaps the label for an inline input.
 13→ */
 14→
 15→import { useCallback, useEffect, useRef, useState } from "react";
 16→import { createPortal } from "react-dom";
 17→import { EllipsisVertical, Pin, Snowflake, Plus, ChevronRight } from "lucide-react";
 18→import type { AgentStatus, Workspace } from "@/lib/types";
 19→import type { AgentClientState } from "@/hooks/use-websocket";
 20→import { Tip } from "@/components/ui/tip";
 21→import { cn } from "@/lib/utils";
 22→import { WorkspaceSwitcher } from "./workspace-switcher";
 23→
 24→/** Status dot color + optional pulse animation. */
 25→const STATUS_DOT: Record<AgentStatus, string> = {
 26→  idle: "bg-muted-foreground",
 27→  spawning: "bg-yellow-500 animate-pulse",
 28→  connected: "bg-green-500",
 29→  thinking: "bg-blue-500 animate-pulse",
 30→  done: "bg-muted-foreground",
 31→  disconnected: "bg-orange-500 animate-pulse",
 32→  error: "bg-red-500",
 33→};
 34→
 35→/** Statuses where the CLI is actively running and can be killed. */
 36→const KILLABLE: Set<AgentStatus> = new Set(["spawning", "connected", "thinking"]);
 37→/** Statuses considered archived (session ended, read-only). */
 38→const ARCHIVED: Set<AgentStatus> = new Set(["done", "disconnected", "error"]);
 39→
 40→interface ContextMenuState {
 41→  agentId: string;
 42→  x: number;
 43→  y: number;
 44→}
 45→
 46→export function AgentSidebar({
 47→  agents,
 48→  agentOrder,
 49→  activeAgentId,
 50→  loading,
 51→  onSelect,
 52→  onNewAgent,
 53→  onKill,
 54→  onDelete,
 55→  onRename,
 56→  onClearHistory,
 57→  onPin,
 58→  onIcebox,
 59→  onMoveAgent,
 60→  workspaces,
 61→  activeWorkspaceId,
 62→  onSelectWorkspace,
 63→  onRenameWorkspace,
 64→  onDeleteWorkspace,
 65→  onOpenFolder,
 66→}: {
 67→  agents: Map<string, AgentClientState>;
 68→  agentOrder: string[];
 69→  activeAgentId: string | null;
 70→  loading?: boolean;
 71→  onSelect: (agentId: string | null) => void;
 72→  onNewAgent: () => void;
 73→  onKill: (agentId: string) => void;
 74→  onDelete: (agentId: string) => void;
 75→  onRename: (agentId: string, label: string) => void;
 76→  onClearHistory: (agentId: string) => void;
 77→  onPin: (agentId: string, pinned: boolean) => void;
 78→  onIcebox: (agentId: string, iceboxed: boolean) => void;
 79→  onMoveAgent: (agentId: string, workspaceId: string | null) => void;
 80→  workspaces: Workspace[];
 81→  activeWorkspaceId: string | null;
 82→  onSelectWorkspace: (workspaceId: string | null) => void;
 83→  onRenameWorkspace: (workspaceId: string, name: string) => void;
 84→  onDeleteWorkspace: (workspaceId: string) => void;
 85→  onOpenFolder: () => void;
 86→}) {
 87→  const [ctxMenu, setCtxMenu] = useState<ContextMenuState | null>(null);
 88→  const [renamingId, setRenamingId] = useState<string | null>(null);
 89→  const menuRef = useRef<HTMLDivElement>(null);
 90→
 91→  // Sort helper: most recent first by createdAt
 92→  const byRecency = (a: string, b: string) => {
 93→    const ca = agents.get(a)?.createdAt ?? 0;
 94→    const cb = agents.get(b)?.createdAt ?? 0;
 95→    return cb - ca;
 96→  };
 97→
 98→  // Split agents into pinned, active, icebox, and archived
 99→  const pinnedIds = agentOrder
100→    .filter((id) => {
101→      const a = agents.get(id);
102→      return a && a.pinned && !a.iceboxed;
103→    })
104→    .sort(byRecency);
105→  const activeIds = agentOrder
106→    .filter((id) => {
107→      const a = agents.get(id);
108→      return a && !a.pinned && !a.iceboxed && !ARCHIVED.has(a.status);
109→    })
110→    .sort(byRecency);
111→  const iceboxIds = agentOrder
112→    .filter((id) => {
113→      const a = agents.get(id);
114→      return a && a.iceboxed;
115→    })
116→    .sort(byRecency);
117→  const archivedIds = agentOrder
118→    .filter((id) => {
119→      const a = agents.get(id);
120→      return a && !a.pinned && !a.iceboxed && ARCHIVED.has(a.status);
121→    })
122→    .sort(byRecency);
123→
124→  // Close context menu on click-outside or Escape
125→  useEffect(() => {
126→    if (!ctxMenu) return;
127→    function handleClick(e: MouseEvent) {
128→      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
129→        setCtxMenu(null);
130→      }
131→    }
132→    function handleKey(e: KeyboardEvent) {
133→      if (e.key === "Escape") setCtxMenu(null);
134→    }
135→    document.addEventListener("mousedown", handleClick);
136→    document.addEventListener("keydown", handleKey);
137→    return () => {
138→      document.removeEventListener("mousedown", handleClick);
139→      document.removeEventListener("keydown", handleKey);
140→    };
141→  }, [ctxMenu]);
142→
143→  const openMenu = useCallback((agentId: string, x: number, y: number) => {
144→    setCtxMenu({ agentId, x, y });
145→  }, []);
146→
147→  const handleContextMenu = useCallback((e: React.MouseEvent, agentId: string) => {
148→    e.preventDefault();
149→    openMenu(agentId, e.clientX, e.clientY);
150→  }, [openMenu]);
151→
152→  const handleMenuButton = useCallback((e: React.MouseEvent, agentId: string) => {
153→    e.stopPropagation();
154→    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
155→    openMenu(agentId, rect.right, rect.bottom);
156→  }, [openMenu]);
157→
158→  const closeMenu = useCallback(() => setCtxMenu(null), []);
159→
160→  function renderAgentRow(id: string, dimmed: boolean) {
161→    const agent = agents.get(id);
162→    if (!agent) return null;
163→    const isActive = id === activeAgentId;
164→    return (
165→      <div
166→        key={id}
167→        onClick={() => onSelect(id)}
168→        onContextMenu={(e) => handleContextMenu(e, id)}
169→        className={cn(
170→          "group flex w-full cursor-pointer items-start gap-0.5 px-3 py-2 text-left text-xs transition-colors",
171→          isActive ? "bg-sidebar-accent" : "hover:bg-sidebar-accent/50",
172→          dimmed && "opacity-60"
173→        )}
174→      >
175→        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
176→          <span className="flex items-center gap-2">
177→            <span className={cn("inline-block size-2 shrink-0 rounded-full", STATUS_DOT[agent.status])} />
178→            {renamingId === id ? (
179→              <RenameInput
180→                initialValue={agent.label}
181→                onConfirm={(label) => {
182→                  onRename(id, label);
183→                  setRenamingId(null);
184→                }}
185→                onCancel={() => setRenamingId(null)}
186→              />
187→            ) : (
188→              <Tip text={agent.label || "new agent"} side="right"><span className="truncate">{agent.label || "new agent"}</span></Tip>
189→            )}
190→            {agent.pinned && (
191→              <Pin className="size-2.5 shrink-0 text-muted-foreground" />
192→            )}
193→            {agent.iceboxed && (
194→              <Snowflake className="size-2.5 shrink-0 text-muted-foreground" />
195→            )}
196→          </span>
197→          <span className="pl-4 text-[10px] text-muted-foreground truncate font-mono">
198→            {id}
199→            {(() => {
200→              const ws = workspaces.find((w) => w.id === agent.workspaceId);
201→              return ws ? <span className="opacity-60"> · {ws.name}</span> : null;
202→            })()}
203→          </span>
204→        </div>
205→        <button
206→          onClick={(e) => handleMenuButton(e, id)}
207→          className="shrink-0 rounded p-0.5 opacity-0 transition-opacity hover:bg-sidebar-accent group-hover:opacity-100"
208→          aria-label="Agent menu"
209→        >
210→          <EllipsisVertical className="size-3.5 text-muted-foreground" />
211→        </button>
212→      </div>
213→    );
214→  }
215→
216→  return (
217→    <div className="flex h-full w-56 flex-col border-r bg-sidebar text-sidebar-foreground">
218→      {/* Workspace switcher */}
219→      <div className="border-b">
220→        <WorkspaceSwitcher
221→          workspaces={workspaces}
222→          activeWorkspaceId={activeWorkspaceId}
223→          onSelect={onSelectWorkspace}
224→          onRename={onRenameWorkspace}
225→          onDelete={onDeleteWorkspace}
226→          onOpenFolder={onOpenFolder}
227→        />
228→      </div>
229→
230→      {/* Header */}
231→      <div className="flex items-center justify-between px-3 py-2">
232→        <span className="text-xs font-semibold">agents</span>
233→        <button
234→          onClick={onNewAgent}
235→          className="rounded-md p-1 hover:bg-sidebar-accent transition-colors"
236→          aria-label="New agent"
237→        >
238→          <Plus className="size-3.5" />
239→        </button>
240→      </div>
241→
242→      {/* Agent list */}
243→      <div className="flex-1 overflow-y-auto">
244→        {loading ? (
245→          <div className="space-y-1 px-3 py-2">
246→            {[...Array(4)].map((_, i) => (
247→              <div key={i} className="flex items-center gap-2 py-2">
248→                <div className="size-2 rounded-full bg-muted-foreground/20 animate-pulse" />
249→                <div className="h-3 flex-1 rounded bg-muted-foreground/20 animate-pulse" style={{ width: `${60 + i * 10}%` }} />
250→              </div>
251→            ))}
252→          </div>
253→        ) : agentOrder.length === 0 ? (
254→          <div className="px-3 py-4 text-xs text-muted-foreground">
255→            No agents yet
256→          </div>
257→        ) : null}
258→
259→        {/* Pinned agents */}
260→        {pinnedIds.length > 0 && (
261→          <>
262→            <div className="flex items-center gap-2 px-3 pt-2 pb-1">
263→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">pinned</span>
264→              <div className="flex-1 border-t" />
265→            </div>
266→            {pinnedIds.map((id) => renderAgentRow(id, false))}
267→          </>
268→        )}
269→
270→        {/* Active agents */}
271→        {activeIds.length > 0 && (
272→          <>
273→            {pinnedIds.length > 0 && (
274→              <div className="flex items-center gap-2 px-3 pt-3 pb-1">
275→                <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">active</span>
276→                <div className="flex-1 border-t" />
277→              </div>
278→            )}
279→            {activeIds.map((id) => renderAgentRow(id, false))}
280→          </>
281→        )}
282→
283→        {/* Icebox agents */}
284→        {iceboxIds.length > 0 && (
285→          <>
286→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
287→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">icebox</span>
288→              <div className="flex-1 border-t" />
289→            </div>
290→            {iceboxIds.map((id) => renderAgentRow(id, true))}
291→          </>
292→        )}
293→
294→        {/* Archived divider + agents */}
295→        {archivedIds.length > 0 && (
296→          <>
297→            <div className="flex items-center gap-2 px-3 pt-3 pb-1">
298→              <span className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">archived</span>
299→              <div className="flex-1 border-t" />
300→            </div>
301→            {archivedIds.map((id) => renderAgentRow(id, true))}
302→          </>
303→        )}
304→      </div>
305→
306→      {/* Context menu — portaled to body to escape sidebar stacking context */}
307→      {ctxMenu && (() => {
308→        const agent = agents.get(ctxMenu.agentId);
309→        if (!agent) return null;
310→        return createPortal(
311→          <div
312→            ref={menuRef}
313→            className="fixed z-[9999] min-w-[160px] rounded-md border bg-popover py-1 text-popover-foreground shadow-md"
314→            style={{ left: ctxMenu.x, top: ctxMenu.y }}
315→          >
316→            <ContextMenuItem
317→              label={agent.pinned ? "Unpin" : "Pin"}
318→              onClick={() => {
319→                onPin(ctxMenu.agentId, !agent.pinned);
320→                closeMenu();
321→              }}
322→            />
323→            <ContextMenuItem
324→              label={agent.iceboxed ? "Un-icebox" : "Icebox"}
325→              onClick={() => {
326→                onIcebox(ctxMenu.agentId, !agent.iceboxed);
327→                closeMenu();
328→              }}
329→            />
330→            {workspaces.length > 0 && (
331→              <ContextMenuSub label="Move to…">
332→                {workspaces
333→                  .filter((w) => w.id !== agent.workspaceId)
334→                  .map((w) => (
335→                    <ContextMenuItem
336→                      key={w.id}
337→                      label={w.name}
338→                      onClick={() => {
339→                        onMoveAgent(ctxMenu.agentId, w.id);
340→                        closeMenu();
341→                      }}
342→                    />
343→                  ))}
344→                {agent.workspaceId && (
345→                  <>
346→                    <div className="my-1 border-t" />
347→                    <ContextMenuItem
348→                      label="No workspace"
349→                      onClick={() => {
350→                        onMoveAgent(ctxMenu.agentId, null);
351→                        closeMenu();
352→                      }}
353→                    />
354→                  </>
355→                )}
356→              </ContextMenuSub>
357→            )}
358→            <ContextMenuItem
359→              label="Rename"
360→              onClick={() => {
361→                setRenamingId(ctxMenu.agentId);
362→                closeMenu();
363→              }}
364→            />
365→            {KILLABLE.has(agent.status) && (
366→              <ContextMenuItem
367→                label="Kill"
368→                onClick={() => {
369→                  onKill(ctxMenu.agentId);
370→                  closeMenu();
371→                }}
372→              />
373→            )}
374→            <ContextMenuItem
375→              label="Clear History"
376→              onClick={() => {
377→                onClearHistory(ctxMenu.agentId);
378→                closeMenu();
379→              }}
380→            />
381→            <div className="my-1 border-t" />
382→            <ContextMenuItem
383→              label="Delete"
384→              destructive
385→              onClick={() => {
386→                closeMenu();
387→                if (confirm("Delete this agent? This cannot be undone.")) {
388→                  onDelete(ctxMenu.agentId);
389→                }
390→              }}
391→            />
392→          </div>,
393→          document.body
394→        );
395→      })()}
396→    </div>
397→  );
398→}
399→
400→/** A single item in the context menu. */
401→function ContextMenuItem({
402→  label,
403→  onClick,
404→  destructive,
405→}: {
406→  label: string;
407→  onClick: () => void;
408→  destructive?: boolean;
409→}) {
410→  return (
411→    <button
412→      onClick={onClick}
413→      className={cn(
414→        "flex w-full px-3 py-1.5 text-xs transition-colors",
415→        destructive
416→          ? "text-red-500 hover:bg-red-500/10"
417→          : "hover:bg-accent"
418→      )}
419→    >
420→      {label}
421→    </button>
422→  );
423→}
424→
425→/** A context menu item with a hover-triggered submenu. */
426→function ContextMenuSub({
427→  label,
428→  children,
429→}: {
430→  label: string;
431→  children: React.ReactNode;
432→}) {
433→  const [open, setOpen] = useState(false);
434→  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
435→
436→  const enter = () => {
437→    if (timeoutRef.current) clearTimeout(timeoutRef.current);
438→    setOpen(true);
