// ── Desk grid layout ──────────────────────────────────────────────────

const COLS = 3;
const DESK_W = 160;
const DESK_H = 140;
const GAP_X = 30;
const GAP_Y = 20;

function deskPosition(index: number) {
  const col = index % COLS;
  const row = Math.floor(index / COLS);
  return {
    x: col * (DESK_W + GAP_X),
    y: row * (DESK_H + GAP_Y),
