const STATUS_ANIM: Record<AgentStatus, string> = {
  idle: "animate-[iso-sway_4s_ease-in-out_infinite]",
  spawning: "animate-[iso-walk_1.2s_ease-out_forwards]",
  connected: "animate-[iso-breathe_3s_ease-in-out_infinite]",
  thinking: "animate-[iso-typing_0.4s_ease-in-out_infinite]",
  done: "animate-[iso-stretch_3s_ease-in-out_infinite]",
  disconnected: "opacity-20",
  error: "animate-[iso-shake_0.3s_ease-in-out_infinite]",
};

const STATUS_DOT_COLOR: Record<AgentStatus, string> = {
  idle: "bg-muted-foreground",
  spawning: "bg-yellow-500",
  connected: "bg-green-500",
  thinking: "bg-blue-500",
  done: "bg-muted-foreground",
  disconnected: "bg-orange-500",
  error: "bg-red-500",
};

/** Map model name fragments to character body color. */
function modelColor(model?: string | null): string {
  if (!model) return "fill-emerald-500";
  const m = model.toLowerCase();
  if (m.includes("opus")) return "fill-purple-500";
  if (m.includes("sonnet")) return "fill-blue-500";
  if (m.includes("haiku")) return "fill-amber-500";
  return "fill-emerald-500";
}

function modelColorBg(model?: string | null): string {
  if (!model) return "bg-emerald-500/20";
  const m = model.toLowerCase();
  if (m.includes("opus")) return "bg-purple-500/20";
  if (m.includes("sonnet")) return "bg-blue-500/20";
  if (m.includes("haiku")) return "bg-amber-500/20";
  return "bg-emerald-500/20";
}

// ── Desk grid layout ──────────────────────────────────────────────────

const COLS = 3;
const DESK_W = 160;
const DESK_H = 140;
const GAP_X = 30;
const GAP_Y = 20;

function deskPosition(index: number) {
  const col = index % COLS;
  const row = Math.floor(index / COLS);
  return {
    x: col * (DESK_W + GAP_X),
    y: row * (DESK_H + GAP_Y),
  };
}

