          <line x1="15" y1="6" x2="18" y2="9" className="stroke-red-500 stroke-[1.5]" />
          <line x1="18" y1="6" x2="15" y2="9" className="stroke-red-500 stroke-[1.5]" />
        </>
      ) : status === "done" ? (
        <>
          {/* Happy closed eyes */}
          <path d="M9 7 Q11.5 5 13 7" className="stroke-background stroke-[1.5]" fill="none" />
          <path d="M15 7 Q17.5 5 19 7" className="stroke-background stroke-[1.5]" fill="none" />
        </>
      ) : (
        <>
          <circle cx="11" cy="7" r="1.2" className="fill-background" />
          <circle cx="17" cy="7" r="1.2" className="fill-background" />
        </>
      )}
      {/* Body */}
      <rect x="8" y="15" width="12" height="12" rx="3" className={bodyFill} />
      {/* Arms */}
      {status === "thinking" ? (
