        </>
      ) : (
        <>
          <rect x="3" y="16" width="5" height="4" rx="2" className={bodyFill} opacity="0.8" />
          <rect x="20" y="16" width="5" height="4" rx="2" className={bodyFill} opacity="0.8" />
        </>
      )}
      {/* Legs */}
      <rect x="9" y="27" width="4" height="6" rx="2" className={bodyFill} opacity="0.7" />
      <rect x="15" y="27" width="4" height="6" rx="2" className={bodyFill} opacity="0.7" />
    </svg>
  );
}

