/* --- Isometric agent world animations --- */

@keyframes iso-breathe {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-1px); }
}

@keyframes iso-typing {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  25% { transform: translateY(-1px) rotate(-1deg); }
  75% { transform: translateY(-1px) rotate(1deg); }
}

@keyframes iso-sway {
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(3deg); }
}

@keyframes iso-walk {
  0% { transform: translateX(-40px) translateY(20px); opacity: 0; }
  20% { opacity: 1; }
  100% { transform: translateX(0) translateY(0); opacity: 1; }
}

@keyframes iso-stretch {
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(1.08); }
}

@keyframes iso-shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-2px); }
  75% { transform: translateX(2px); }
}

@keyframes iso-steam {
  0% { transform: translateY(0) scale(1); opacity: 0.6; }
  100% { transform: translateY(-8px) scale(1.3); opacity: 0; }
}

@keyframes thought-pulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 1; }
}

@keyframes iso-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}

@keyframes screen-flicker {
  0%, 100% { opacity: 0.7; }
  50% { opacity: 1; }
}

