"use client";

/**
 * Isometric "agent world" view — a cozy room where each agent is a little
 * character sitting at a desk. Status maps to character pose/animation.
 * Click an agent to select it (switches activeAgentId).
 */

import { useMemo } from "react";
import { ArrowLeft, Sun, CloudLightning, Monitor } from "lucide-react";
import { Tip } from "@/components/ui/tip";
import { cn } from "@/lib/utils";
import type { AgentStatus } from "@/lib/types";
import type { AgentClientState } from "@/hooks/use-websocket";

// ── Status → character animation class ────────────────────────────────

const STATUS_ANIM: Record<AgentStatus, string> = {
  idle: "animate-[iso-idle_6s_ease-in-out_infinite]",
  spawning: "animate-[iso-bounce_1s_ease-out_infinite]",
  connected: "animate-[iso-breathe_4s_ease-in-out_infinite]",
  thinking: "animate-[iso-typing_0.6s_ease-in-out_infinite]",
  done: "animate-[iso-stretch_4s_ease-in-out_infinite]",
  disconnected: "opacity-20",
  error: "animate-[iso-shake_0.5s_ease-in-out_infinite]",
};

const STATUS_DOT_COLOR: Record<AgentStatus, string> = {
  idle: "bg-muted-foreground",
  spawning: "bg-yellow-500",
  connected: "bg-green-500",
  thinking: "bg-blue-500",
  done: "bg-muted-foreground",
  disconnected: "bg-orange-500",
  error: "bg-red-500",
};

/** Map model name fragments to character body color. */
function modelColor(model?: string | null): string {
  if (!model) return "fill-emerald-500";
  const m = model.toLowerCase();
  if (m.includes("opus")) return "fill-purple-500";
  if (m.includes("sonnet")) return "fill-blue-500";
  if (m.includes("haiku")) return "fill-amber-500";
  return "fill-emerald-500";
}

function modelColorBg(model?: string | null): string {
  if (!model) return "bg-emerald-500/20";
  const m = model.toLowerCase();
  if (m.includes("opus")) return "bg-purple-500/20";
  if (m.includes("sonnet")) return "bg-blue-500/20";
  if (m.includes("haiku")) return "bg-amber-500/20";
  return "bg-emerald-500/20";
}

// ── Desk grid layout ──────────────────────────────────────────────────

const DESK_W = 160;

// ── Sub-components ────────────────────────────────────────────────────

/** Chibi-style character — oversized round head, tiny body, expressive face. */
function Character({ status, model }: { status: AgentStatus; model?: string | null }) {
  const bodyFill = modelColor(model);

  if (status === "disconnected") return null;

  return (
    <svg
      width="40"
      height="48"
      viewBox="0 0 40 48"
      className={cn("transition-all duration-300", STATUS_ANIM[status])}
    >
      {/* Shadow blob */}
      <ellipse cx="20" cy="46" rx="10" ry="2" className="fill-foreground/5" />

      {/* Body — small rounded rectangle */}
      <rect x="13" y="30" width="14" height="10" rx="5" className={bodyFill} />

      {/* Arms */}
      {status === "thinking" ? (
        <>
          {/* Arms forward on keyboard */}
          <ellipse cx="10" cy="35" rx="3.5" ry="2.5" className={bodyFill} opacity="0.85" />
          <ellipse cx="30" cy="35" rx="3.5" ry="2.5" className={bodyFill} opacity="0.85" />
        </>
      ) : status === "done" ? (
        <>
          {/* Arms up celebrating */}
          <ellipse cx="8" cy="26" rx="3" ry="2.5" className={bodyFill} opacity="0.85" />
          <ellipse cx="32" cy="26" rx="3" ry="2.5" className={bodyFill} opacity="0.85" />
        </>
      ) : (
        <>
          {/* Arms at sides */}
          <ellipse cx="10" cy="34" rx="3" ry="2.5" className={bodyFill} opacity="0.85" />
          <ellipse cx="30" cy="34" rx="3" ry="2.5" className={bodyFill} opacity="0.85" />
        </>
      )}

      {/* Feet — little round nubs */}
      <ellipse cx="16" cy="41" rx="3.5" ry="2.5" className={bodyFill} opacity="0.7" />
      <ellipse cx="24" cy="41" rx="3.5" ry="2.5" className={bodyFill} opacity="0.7" />

      {/* Head — big chunky circle */}
      <circle cx="20" cy="17" r="14" className={bodyFill} />
      {/* Face area — lighter inner circle */}
      <circle cx="20" cy="18" r="11" className="fill-foreground/80" />

      {/* Eyes — status-dependent */}
      {status === "error" ? (
        <>
          {/* X X eyes */}
          <g className="stroke-red-400" strokeWidth="1.8" strokeLinecap="round">
            <line x1="13" y1="15" x2="16" y2="18" />
            <line x1="16" y1="15" x2="13" y2="18" />
            <line x1="24" y1="15" x2="27" y2="18" />
            <line x1="27" y1="15" x2="24" y2="18" />
          </g>
        </>
      ) : status === "done" ? (
        <>
          {/* Happy ^ ^ eyes */}
          <path d="M12 17 Q14.5 14 17 17" className="stroke-background" strokeWidth="1.8" fill="none" strokeLinecap="round" />
          <path d="M23 17 Q25.5 14 28 17" className="stroke-background" strokeWidth="1.8" fill="none" strokeLinecap="round" />
        </>
      ) : status === "idle" ? (
        <>
          {/* Relaxed half-closed eyes */}
          <g style={{ animation: "iso-blink 5s ease-in-out infinite" }}>
            <ellipse cx="14.5" cy="16.5" rx="2.5" ry="2" className="fill-background" />
            <circle cx="14.5" cy="16" r="1.2" className="fill-foreground/60" style={{ animation: "iso-look 8s ease-in-out infinite" }} />
          </g>
          <g style={{ animation: "iso-blink 5s ease-in-out 0.1s infinite" }}>
            <ellipse cx="25.5" cy="16.5" rx="2.5" ry="2" className="fill-background" />
            <circle cx="25.5" cy="16" r="1.2" className="fill-foreground/60" style={{ animation: "iso-look 8s ease-in-out infinite" }} />
          </g>
        </>
      ) : status === "thinking" ? (
        <>
          {/* Focused eyes — looking slightly up */}
          <g style={{ animation: "iso-blink 4s ease-in-out infinite" }}>
            <ellipse cx="14.5" cy="16" rx="2.5" ry="2.5" className="fill-background" />
            <circle cx="14.5" cy="15" r="1.5" className="fill-foreground/70" />
          </g>
          <g style={{ animation: "iso-blink 4s ease-in-out 0.15s infinite" }}>
            <ellipse cx="25.5" cy="16" rx="2.5" ry="2.5" className="fill-background" />
            <circle cx="25.5" cy="15" r="1.5" className="fill-foreground/70" />
          </g>
        </>
      ) : (
        <>
          {/* Default open eyes with blink + look */}
          <g style={{ animation: "iso-blink 4s ease-in-out infinite" }}>
            <ellipse cx="14.5" cy="16.5" rx="2.5" ry="2.5" className="fill-background" />
            <circle cx="14.5" cy="16.5" r="1.5" className="fill-foreground/70" style={{ animation: "iso-look 6s ease-in-out infinite" }} />
          </g>
          <g style={{ animation: "iso-blink 4s ease-in-out 0.1s infinite" }}>
            <ellipse cx="25.5" cy="16.5" rx="2.5" ry="2.5" className="fill-background" />
            <circle cx="25.5" cy="16.5" r="1.5" className="fill-foreground/70" style={{ animation: "iso-look 6s ease-in-out infinite" }} />
          </g>
        </>
      )}

      {/* Blush cheeks */}
      <circle cx="10" cy="21" r="2.5" className={bodyFill} opacity="0.3" />
      <circle cx="30" cy="21" r="2.5" className={bodyFill} opacity="0.3" />

      {/* Mouth — status-dependent */}
      {status === "error" ? (
        <path d="M17 23 Q20 21 23 23" className="stroke-red-400" strokeWidth="1.2" fill="none" strokeLinecap="round" />
      ) : status === "done" ? (
        <path d="M16 22 Q20 26 24 22" className="stroke-background" strokeWidth="1.2" fill="none" strokeLinecap="round" />
      ) : status === "thinking" ? (
        <ellipse cx="20" cy="23" rx="1.5" ry="1.8" className="fill-background/60" />
      ) : (
        <path d="M17 22.5 Q20 25 23 22.5" className="stroke-background" strokeWidth="1" fill="none" strokeLinecap="round" />
      )}
    </svg>
  );
}

/** Thought bubble for thinking agents. */
function ThoughtBubble() {
  return (
    <div className="absolute -top-8 left-1/2 -translate-x-1/2 animate-[thought-pulse_1.5s_ease-in-out_infinite]">
      <div className="rounded-full bg-muted px-2 py-0.5 text-[10px] text-muted-foreground font-mono shadow-sm">
        ...
      </div>
      <div className="mx-auto mt-0.5 size-1.5 rounded-full bg-muted" />
      <div className="mx-auto mt-0.5 size-1 rounded-full bg-muted" />
    </div>
  );
}

/** Error exclamation mark floating above. */
function ErrorBang() {
  return (
    <div className="absolute -top-6 left-1/2 -translate-x-1/2 animate-[iso-float_1s_ease-in-out_infinite]">
      <span className="text-sm font-bold text-red-500">!</span>
    </div>
  );
}

/** Coffee cup for idle agents. */
function CoffeeCup() {
  return (
    <div className="absolute -right-3 top-1">
      <div className="relative">
        <div className="size-3 rounded-b-sm bg-amber-800/60 border border-amber-700/40" />
        {/* Steam */}
        <div className="absolute -top-2 left-0.5 w-0.5 h-2 bg-muted-foreground/30 rounded-full animate-[iso-steam_2s_ease-out_infinite]" />
        <div className="absolute -top-2 left-1.5 w-0.5 h-2 bg-muted-foreground/20 rounded-full animate-[iso-steam_2s_ease-out_0.5s_infinite]" />
      </div>
    </div>
  );
}

/** A single desk + monitor + chair + character workstation. */
function Workstation({
  agent,
  agentId,
  active,
  onSelect,
}: {
  agent: AgentClientState;
  agentId: string;
  active: boolean;
  onSelect: () => void;
}) {
  const lastTool = agent.messages.at(-1)?.toolCalls?.at(-1)?.name;
  const elapsed = Math.floor((Date.now() - agent.createdAt) / 60000);
  const elapsedLabel = elapsed < 1 ? "<1m" : elapsed < 60 ? `${elapsed}m` : `${Math.floor(elapsed / 60)}h${elapsed % 60}m`;

  const tooltipText = [
    agent.label || "new agent",
    agent.model ? `model: ${agent.model}` : null,
    `status: ${agent.status}`,
    lastTool ? `tool: ${lastTool}` : null,
    `age: ${elapsedLabel}`,
  ]
    .filter(Boolean)
    .join("\n");

  return (
    <Tip text={tooltipText} side="top">
      <button
        onClick={onSelect}
        className={cn(
          "relative flex flex-col items-center rounded-lg p-3 transition-all duration-200",
          "hover:bg-muted/40 hover:scale-[1.02]",
          active && "ring-1 ring-primary/50 bg-muted/30",
          "focus:outline-none focus-visible:ring-2 focus-visible:ring-primary"
        )}
        style={{ width: DESK_W }}
      >
        {/* Character area */}
        <div className="relative mb-2 flex items-end justify-center" style={{ height: 48 }}>
          <Character status={agent.status} model={agent.model} />
          {agent.status === "thinking" && <ThoughtBubble />}
          {agent.status === "error" && <ErrorBang />}
          {agent.status === "idle" && <CoffeeCup />}
        </div>

        {/* Desk surface */}
        <div className={cn(
          "relative flex w-full items-center justify-center rounded-md border px-2 py-1.5",
          "bg-card/80 shadow-sm",
          agent.status === "disconnected" && "opacity-40"
        )}>
          {/* Monitor */}
          <div className="relative mr-2">
            <Monitor className={cn(
              "size-4",
              agent.status === "thinking"
                ? "text-blue-400 animate-[screen-flicker_2s_ease-in-out_infinite]"
                : agent.status === "disconnected"
                  ? "text-muted-foreground/30"
                  : "text-muted-foreground/60"
            )} />
            {agent.status === "thinking" && (
              <div className="absolute inset-0 rounded-sm bg-blue-500/10 blur-sm" />
            )}
          </div>

          {/* Active tool label */}
          {lastTool && (agent.status === "thinking" || agent.status === "connected") ? (
            <span className="truncate text-[9px] font-mono text-muted-foreground/70">
              {lastTool}
            </span>
          ) : (
            <span className="text-[9px] text-muted-foreground/40">
              {agent.status === "disconnected" ? "offline" : "desk"}
            </span>
          )}
        </div>

        {/* Chair (empty if disconnected) */}
        <div className={cn(
          "mt-1 h-1.5 w-8 rounded-full",
          agent.status === "disconnected"
            ? "bg-muted-foreground/10 rotate-12"
            : modelColorBg(agent.model)
        )} />

        {/* Name tag + status dot */}
        <div className="mt-2 flex items-center gap-1.5">
          <span className={cn("size-1.5 shrink-0 rounded-full", STATUS_DOT_COLOR[agent.status])} />
          <span className="max-w-[100px] truncate text-[10px] text-foreground/70">
            {agent.label || "new agent"}
          </span>
        </div>

        {/* Agent ID */}
        <span className="mt-0.5 text-[8px] font-mono text-muted-foreground/40">
          {agentId.slice(0, 8)}
        </span>
      </button>
    </Tip>
  );
}

// ── Ambient decorations ───────────────────────────────────────────────

function Plant() {
  return (
    <div className="flex flex-col items-center animate-[iso-sway_5s_ease-in-out_infinite]">
      {/* Leaves */}
      <div className="relative">
        <div className="size-5 rounded-full bg-green-700/50" />
        <div className="absolute -left-1 top-1 size-4 rounded-full bg-green-600/40" />
        <div className="absolute -right-1 top-1 size-4 rounded-full bg-green-800/40" />
      </div>
      {/* Pot */}
      <div className="h-3 w-4 rounded-b-md bg-amber-800/50 -mt-1" />
    </div>
  );
}

function Bookshelf() {
  return (
    <div className="flex flex-col gap-0.5">
      <div className="flex gap-[2px]">
        <div className="h-5 w-2 rounded-t-sm bg-blue-800/40" />
        <div className="h-5 w-1.5 rounded-t-sm bg-red-800/40" />
        <div className="h-5 w-2 rounded-t-sm bg-green-800/40" />
        <div className="h-5 w-1.5 rounded-t-sm bg-yellow-800/30" />
        <div className="h-5 w-2 rounded-t-sm bg-purple-800/40" />
      </div>
      <div className="h-0.5 w-full bg-muted-foreground/20 rounded" />
      <div className="flex gap-[2px]">
        <div className="h-4 w-1.5 rounded-t-sm bg-indigo-800/40" />
        <div className="h-4 w-2 rounded-t-sm bg-orange-800/40" />
        <div className="h-4 w-2 rounded-t-sm bg-teal-800/40" />
      </div>
      <div className="h-0.5 w-full bg-muted-foreground/20 rounded" />
    </div>
  );
}

function CoffeeMachine() {
  return (
    <div className="flex flex-col items-center">
      <div className="h-6 w-5 rounded-t-md bg-muted-foreground/20 border border-muted-foreground/10" />
      <div className="h-1 w-6 bg-muted-foreground/15 rounded-b" />
      {/* Steam */}
      <div className="absolute -top-2 left-1 w-0.5 h-2 bg-muted-foreground/20 rounded-full animate-[iso-steam_3s_ease-out_infinite]" />
    </div>
  );
}

// ── Resource bar ──────────────────────────────────────────────────────

function ResourceBar({ agents, onBack }: { agents: Map<string, AgentClientState>; onBack?: () => void }) {
  const stats = useMemo(() => {
    let active = 0;
    let thinking = 0;
    let errors = 0;
    let total = 0;
    agents.forEach((a) => {
      total++;
      if (a.status === "thinking" || a.status === "connected" || a.status === "spawning") active++;
      if (a.status === "thinking") thinking++;
      if (a.status === "error") errors++;
    });
    return { active, thinking, errors, total };
  }, [agents]);

  return (
    <div className="flex items-center gap-4 border-b px-4 py-2 text-xs">
      {onBack && (
        <button
          onClick={onBack}
          className="rounded p-1 transition-colors hover:bg-muted/50"
          title="Back to chat"
        >
          <ArrowLeft className="size-3.5" />
        </button>
      )}
      <span className="font-semibold text-foreground/70">agent world</span>
      <span className="text-muted-foreground">
        {stats.active} active / {stats.total} total
      </span>
      {stats.thinking > 0 && (
        <span className="flex items-center gap-1 text-blue-400">
          <span className="size-1.5 rounded-full bg-blue-500 animate-pulse" />
          {stats.thinking} thinking
        </span>
      )}
      <span className="ml-auto flex items-center gap-1">
        {stats.errors > 0 ? (
          <CloudLightning className="size-3.5 text-red-400" />
        ) : (
          <Sun className="size-3.5 text-yellow-500/70" />
        )}
        <span className={stats.errors > 0 ? "text-red-400" : "text-muted-foreground"}>
          {stats.errors > 0 ? `${stats.errors} error${stats.errors > 1 ? "s" : ""}` : "all clear"}
        </span>
      </span>
    </div>
  );
}

// ── Main component ────────────────────────────────────────────────────

export function AgentWorld({
  agents,
  agentOrder,
  activeAgentId,
  onSelect,
  onBack,
}: {
  agents: Map<string, AgentClientState>;
  agentOrder: string[];
  activeAgentId: string | null;
  onSelect: (agentId: string) => void;
  onBack?: () => void;
}) {
  // Only show active agents (not done/disconnected/error/iceboxed)
  const ACTIVE_STATUSES = new Set(["idle", "spawning", "connected", "thinking"]);
  const visibleIds = useMemo(
    () => agentOrder.filter((id) => {
      const a = agents.get(id);
      return a && !a.iceboxed && ACTIVE_STATUSES.has(a.status);
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [agentOrder, agents]
  );

  return (
    <div className="flex h-full flex-col bg-background">
      <ResourceBar agents={agents} onBack={onBack} />

      <div className="relative flex-1 overflow-auto">
        {/* Isometric floor grid */}
        <div
          className="absolute inset-0 opacity-[0.04]"
          style={{
            backgroundImage: `
              linear-gradient(to right, currentColor 1px, transparent 1px),
              linear-gradient(to bottom, currentColor 1px, transparent 1px)
            `,
            backgroundSize: "40px 40px",
          }}
        />

        {visibleIds.length === 0 ? (
          <div className="flex h-full items-center justify-center">
            <div className="text-center text-muted-foreground">
              <div className="text-4xl mb-2">~</div>
              <p className="text-sm">No agents yet</p>
              <p className="text-xs mt-1">Spawn one from the chat view</p>
            </div>
          </div>
        ) : (
          <div className="flex h-full flex-col items-center p-8">
            {/* Decorations row */}
            <div className="flex items-end gap-8 mb-8 opacity-60">
              <Plant />
              <Bookshelf />
              <div className="relative">
                <CoffeeMachine />
              </div>
              <Plant />
            </div>

            {/* Agent desk grid — centered, wraps naturally */}
            <div className="flex flex-wrap justify-center gap-4">
              {visibleIds.map((id) => {
                const agent = agents.get(id);
                if (!agent) return null;
                return (
                  <Workstation
                    key={id}
                    agent={agent}
                    agentId={id}
                    active={id === activeAgentId}
                    onSelect={() => onSelect(id)}
                  />
                );
              })}
            </div>
          </div>
        )}

        {/* Floor shadow gradient at bottom */}
        <div className="pointer-events-none absolute bottom-0 left-0 right-0 h-24 bg-gradient-to-t from-background/80 to-transparent" />
      </div>
    </div>
  );
}

